def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    bal: dict[str, int] = {}
    frozen: set[str] = set()
    hist: list[tuple] = []
    rejected: list[int] = []

    def amount(tok: str):
        if tok and all("0" <= c <= "9" for c in tok):
            return int(tok)
        return None

    for i, op in enumerate(ops):
        p = op.split(" ")
        v = p[0] if p else ""
        n = len(p)
        if v == "open" and n == 3:
            a, x = p[1], amount(p[2])
            if x is None or x < 0 or a in bal:
                rejected.append(i)
            else:
                bal[a] = x
                hist.append(("open", a))
        elif v == "deposit" and n == 3:
            a, x = p[1], amount(p[2])
            if x is None or x <= 0 or a not in bal:
                rejected.append(i)
            else:
                bal[a] += x
                hist.append(("deposit", a, x))
        elif v == "withdraw" and n == 3:
            a, x = p[1], amount(p[2])
            if x is None or x <= 0 or a not in bal or a in frozen or bal[a] < x:
                rejected.append(i)
            else:
                bal[a] -= x
                hist.append(("withdraw", a, x))
        elif v == "transfer" and n == 4:
            a, b, x = p[1], p[2], amount(p[3])
            if (
                x is None
                or x <= 0
                or a == b
                or a not in bal
                or b not in bal
                or a in frozen
                or bal[a] < x
            ):
                rejected.append(i)
            else:
                bal[a] -= x
                bal[b] += x
                hist.append(("transfer", a, b, x))
        elif v == "freeze" and n == 2:
            a = p[1]
            if a not in bal or a in frozen:
                rejected.append(i)
            else:
                frozen.add(a)
                hist.append(("freeze", a))
        elif v == "unfreeze" and n == 2:
            a = p[1]
            if a not in bal or a not in frozen:
                rejected.append(i)
            else:
                frozen.remove(a)
                hist.append(("unfreeze", a))
        elif v == "undo" and n == 1:
            if not hist:
                rejected.append(i)
            else:
                rec = hist.pop()
                kind = rec[0]
                if kind == "open":
                    del bal[rec[1]]
                elif kind == "deposit":
                    bal[rec[1]] -= rec[2]
                elif kind == "withdraw":
                    bal[rec[1]] += rec[2]
                elif kind == "transfer":
                    bal[rec[1]] += rec[3]
                    bal[rec[2]] -= rec[3]
                elif kind == "freeze":
                    frozen.remove(rec[1])
                else:
                    frozen.add(rec[1])
        else:
            rejected.append(i)
    return bal, rejected
